#include <iostream>
#include <string>
using namespace std;
class Person{protected:string name; public:Person(string n):name(n){}};
class Employee:public Person{protected:int id; public:Employee(string n,int i):Person(n),id(i){}};
class Manager:public Employee{string dept; public:Manager(string n,int i,string d):Employee(n,i),dept(d){} void show(){cout<<name<<" "<<id<<" "<<dept;}};
int main(){Manager m("Ravi",101,"Sales");m.show();}

#include <iostream>
using namespace std;
class Shape{public:virtual double area() const=0; virtual ~Shape()=default;};
class Circle:public Shape{double r;public:Circle(double x):r(x){} double area()const override{return 3.14159*r*r;}};
class Rectangle:public Shape{double w,h;public:Rectangle(double a,double b):w(a),h(b){} double area()const override{return w*h;}};
int main(){Circle c(2);Rectangle r(3,4);Shape* s[]={&c,&r};for(auto p:s)cout<<p->area()<<"\n";}

